file.content:
        items.append((event_id, ttl_seconds))

    engine = request.app.state.engine
    result = grants.issue_grants_batch(engine, machine_id=machine_id, items=items)
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "event_not_allowed":
        return error_response(409, "event_not_allowed")
    if status == "decision_basis_unavailable":
        return error_response(409, "decision_basis_unavailable")
    if status == "decision_basis_invalid":
        return error_response(409, "decision_basis_invalid")
    if status == "grant_already_exists":
        return error_response(409, "grant_already_exists")
    if status == "machine_suspended":
        return error_response(409, "machine_suspended")
    return [AuthorizationGrantOut(**grant) for grant in result["grants"]]


@app.post(
    "/machines/{machine_id}/authorization-grants/{grant_id}/consume",
    response_model=AuthorizationGrantUseOut,
)
async def consume_authorization_grant(
    machine_id: str, grant_id: str, request: Request
):
    """Atomically consume one unused, unexpired grant exactly once.

    The request accepts only an empty query string and an empty request body:
    any query parameter, a repeated parameter, or any carried body (including
    an empty JSON object) is
    ``422 {"error":{"code":"invalid_query"}}`` validated before the machine or
    grant is read, so the same malformed request against a non-existent
    machine is still 422. After validation a missing machine, a missing grant,
    or a grant owned by another machine is
    ``404 {"error":{"code":"not_found"}}``. Consuming an already-consumed
    grant answers ``409 grant_consumed``, consuming an emergency-revoked
    grant answers ``409 grant_revoked``, and a grant past its ``expires_at``
    answers ``409 grant_expired``; these outcomes keep their precedence and
    do not change when the machine is suspended. Only a still-unconsumed,
    unrevoked, unexpired grant on a suspended machine answers
    ``409 machine_suspended``; none of these writes anything. On success
    the grant flips to ``consumed`` and its single use record is inserted in
    one locked write transaction, so a concurrent consumption burst has
    exactly one ``200`` success carrying ``{grant_id, use_id, consumed_at}``;
    the state change and the use record commit together or leave no trace.
    A revocation racing this consumption has one definite terminal winner.
    The machine status change takes the same write lock, so a suspension that
    commits first turns the consumption into ``machine_suspended`` while a
    consumption that commits first keeps its unique success; after the
    machine returns to active the same still-valid grant consumes normally.
    """
    if request.query_params:
        return error_response(422, "invalid_query")
    content_length = request.headers.get("content-length")
    if (content_length is not None and content_length != "0") or (
        content_length is None and "transfer-encoding" in request.headers
    ):
        return error_response(422, "invalid_query")

    engine = request.app.state.engine
    result = grants.consume_grant(
        engine, machine_id=machine_id, grant_id=grant_id
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "grant_consumed":
        return error_response(409, "grant_consumed")
    if status == "grant_revoked":
        return error_response(409, "grant_revoked")
    if status == "grant_expired":
        return error_response(409, "grant_expired")
    if status == "machine_suspended":
        return error_response(409, "machine_suspended")
    return AuthorizationGrantUseOut(**result["use"])


@app.post(
    "/machines/{machine_id}/authorization-grants/batch-consume",
    response_model=list[AuthorizationGrantUseOut],
)
async def consume_authorization_grants_batch(machine_id: str, request: Request):
    """Atomically consume several unused, unexpired grants, or none.

    The request carries no query string and a JSON object body with exactly
    one field: ``grant_ids``, an array of 1 to 100 distinct, non-empty
    strings naming grants of the path machine, in the order they are to be
    confirmed. Validation runs before any machine or grant is read:

    - any query parameter (or repeated parameter) is
      ``422 {"error":{"code":"invalid_query"}}`` — even against a
      non-existent machine the query check still wins;
    - a missing body, a body that is not a JSON object, a missing or extra
      top-level field, a ``grant_ids`` value that is not an array of 1 to
      100 elements, an element that is not a string or is blank after
      trimming, or a repeated grant id is
      ``422 {"error":{"code":"invalid_grant_request"}}``.

    After validation a missing machine, a missing grant, or a grant owned
    by another machine is ``404 {"error":{"code":"not_found"}}``. Every
    grant is then checked in input order against exactly the
    single-consume rules, and the first failing grant decides the whole
    batch: an already-consumed grant answers ``409 grant_consumed``, an
    emergency-revoked grant answers ``409 grant_revoked``, a grant past its
    ``expires_at`` answers ``409 grant_expired``, and a still-usable grant
    on a suspended machine answers ``409 machine_suspended`` — the terminal
    and derived outcomes keep their precedence even while the machine is
    suspended. A rejected batch writes nothing: no state flip, no use
    record, no lifecycle event, no partial consumption. On success every
    grant flips to ``consumed`` and its single use record is inserted in
    one locked write transaction — the same lock the single consume, the
    revocation, and the machine status change take — so a concurrent
    single consume or another batch racing for any of these grants has
    exactly one winner and the loser rolls back entirely, reporting the
    first raced grant's conflict in its own input order. The success body
    is the array of ``{grant_id, use_id, consumed_at}`` objects in input
    order, one per grant, every ``consumed_at`` the same UTC ``Z`` commit
    moment of the batch.
    """
    # Query validation precedes body parsing and every database read.
    if request.query_params:
        return error_response(422, "invalid_query")

    try:
        payload = await request.json()
    except Exception:
        return error_response(422, "invalid_grant_request")
    if not isinstance(payload, dict) or set(payload) != {"grant_ids"}:
        return error_response(422, "invalid_grant_request")

    raw_grant_ids = payload["grant_ids"]
    if not isinstance(raw_grant_ids, list) or not 1 <= len(raw_grant_ids) <= 100:
        return error_response(422, "invalid_grant_request")

    grant_ids: list[str] = []
    seen_grant_ids: set[str] = set()
    for element in raw_grant_ids:
        # The elements follow the other path-scoped identifiers: a
        # non-string or blank-after-trim value is an illegal body, not a
        # looked-up object, and a repeated id within one batch is the same
        # single invalid_grant_request outcome.
        if isinstance(element, bool) or not isinstance(element, str):
            return error_response(422, "invalid_grant_request")
        grant_id = element.strip()
        if not grant_id:
            return error_response(422, "invalid_grant_request")
        if grant_id in seen_grant_ids:
            return error_response(422, "invalid_grant_request")
        seen_grant_ids.add(grant_id)
        grant_ids.append(grant_id)

    engine = request.app.state.engine
    result = grants.consume_grants_batch(
        engine, machine_id=machine_id, grant_ids=grant_ids
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "grant_consumed":
        return error_response(409, "grant_consumed")
    if status == "grant_revoked":
        return error_response(409, "grant_revoked")
    if status == "grant_expired":
        return error_response(409, "grant_expired")
    if status == "machine_suspended":
        return error_response(409, "machine_suspended")
    return [AuthorizationGrantUseOut(**use) for use in result["uses"]]


@app.post(
    "/machines/{machine_id}/authorization-grants/{grant_id}/revoke",
    response_model=AuthorizationGrantRevocationOut,
)
async def revoke_authorization_grant(
    machine_id: str, grant_id: str, request: Request
):
    """Emergency-revoke one unconsumed, unrevoked, unexpired grant.

    The request accepts only an empty query string and an empty request body:
    any query parameter, a repeated parameter, or any carried body (including
    an empty JSON object) is
    ``422 {"error":{"code":"invalid_query"}}`` validated before the machine or
    grant is read, so the same malformed request against a non-existent
    machine is still 422. After validation a missing machine, a missing grant,
    or a grant owned by another machine is
    ``404 {"error":{"code":"not_found"}}``. Revoking an already-consumed grant
    answers ``409 grant_consumed``, revoking an already-revoked grant answers
    ``409 grant_revoked``, and revoking a grant past its ``expires_at``
    answers ``409 grant_expired``; none of these writes anything. On success
    the grant flips to ``revoked`` and ``revoked_at`` is stamped in one locked
    write transaction — the same lock the consume operation takes — so a
    concurrent revocation burst has exactly one ``200`` success and a
    revocation racing a consumption has one definite terminal winner: consume
    first makes this call answer ``grant_consumed``; revoke first makes the
    consumption answer ``grant_revoked``. The success body is
    ``{grant_id, revoked_at, status}`` with ``status "revoked"`` and
    ``revoked_at`` a UTC ``Z`` RFC 3339 instant. Revocation changes only the
    grant's own status and stamp: it never modifies the decision event, the
    immutable decision basis, any hash chain, evidence, incident, diagnostic,
    or export, and adds no renewal, transfer, or deletion entry.
    """
    if request.query_params:
        return error_response(422, "invalid_query")
    content_length = request.headers.get("content-length")
    if (content_length is not None and content_length != "0") or (
        content_length is None and "transfer-encoding" in request.headers
    ):
        return error_response(422, "invalid_query")

    engine = request.app.state.engine
    result = grants.revoke_grant(
        engine, machine_id=machine_id, grant_id=grant_id
    )
    status = result["status"]
    if status == "not_found":
        return error_response(404, "not_found")
    if status == "grant_consumed":
        return error_response(409, "grant_consumed")

"""Tests for the batch consumption of one-time authorization grants.

    POST /machines/{machine_id}/authorization-grants/batch-consume

The batch entry confirms the use of several grants of one machine in a
single all-or-nothing action: the body is exactly ``{"grant_ids": [...]}``
with 1..100 distinct, blank-free strings in input order; every grant is
checked in input order against exactly the single-consume rules, the first
failing grant decides the whole batch's outcome, and a failure writes
nothing at all. A successful batch flips every grant to ``consumed``,
inserts exactly one use record per grant, and appends one ``consumed``
lifecycle event per grant, all stamped with one shared UTC consume moment.
These tests cover the success shape, every validation and lookup outcome,
the per-item failure precedence, atomicity (no partial consumption),
concurrency against the single consume and against another batch, the
suspended-machine gate, and non-interference with the single-consume
entry.
"""
import threading
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timedelta, timezone

import pytest
