input.content:
"""Tests for the batch emergency revocation of one-time authorization grants.

    POST /machines/{machine_id}/authorization-grants/batch-revoke

The batch entry emergency-revokes several grants of one machine in a single
all-or-nothing action: the body is exactly ``{"grant_ids": [...]}`` with
1..100 distinct, blank-free strings in input order; every grant is checked
in input order against exactly the single-revocation rules (with no
suspended-machine gate), the first failing grant decides the whole batch's
outcome, and a failure writes nothing at all. A successful batch flips
every grant to ``revoked``, stamps one shared ``revoked_at``, and appends
one ``revoked`` lifecycle event per grant, all in one locked write
transaction. These tests cover the success shape, every validation and
lookup outcome, the per-item failure precedence, atomicity (no partial
revocation), the suspended-machine non-gate, concurrency against the
single revoke, the single consume, and the batch consume, and
non-interference with the single-revoke entry.
"""
import threading
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timedelta, timezone

import pytest
from fastapi.testclient import TestClient
from sqlalchemy import text

from accountability.app import app


@pytest.fixture
def client(tmp_path, monkeypatch):
    monkeypatch.setenv(
        "ACCOUNTABILITY_DATABASE_URL", f"sqlite:///{tmp_path / 'test.db'}"
    )
    with TestClient(app) as test_client:
        yield test_client


def create_machine(client, external_id="machine-1"):
    response = client.post(
        "/machines",
        json={
            "external_id": external_id,
            "display_name": "Machine One",
            "public_key": "key-1",
        },
    )
    assert response.status_code == 201
    return response.json()["id"]


def create_rule(client, action_type="read", resource_pattern="res/*",
                effect="allow", priority=0):
    response = client.post(
        "/policy-rules",
        json={
            "action_type": action_type,
            "resource_pattern": resource_pattern,
            "effect": effect,
            "priority": priority,
        },
    )
    assert response.status_code == 201
    return response.json()


def declare(client, machine_id, action_type="read", resource_pattern="res/*",
            enabled=True):
    response = client.post(
        f"/machines/{machine_id}/behavior-declarations",
        json={
            "action_type": action_type,
            "resource_pattern": resource_pattern,
            "enabled": enabled,
        },
    )
    assert response.status_code == 201
    return response.json()


def record_event(client, machine_id, action_type="read", resource="res/x"):
    return client.post(
        f"/machines/{machine_id}/authorization-decision-events",
        json={"action_type": action_type, "resource": resource},
    )


def issue(client, machine_id, event_id, ttl_seconds=60):
    response = client.post(
        f"/machines/{machine_id}/authorization-grants",
        json={"event_id": event_id, "ttl_seconds": ttl_seconds},
    )
    assert response.status_code == 201
    return response.json()


def batch_revoke_url(machine_id):
    return f"/machines/{machine_id}/authorization-grants/batch-revoke"


def batch_consume_url(machine_id):
    return f"/machines/{machine_id}/authorization-grants/batch-consume"


def revoke_url(machine_id, grant_id):
    return (
        f"/machines/{machine_id}/authorization-grants/{grant_id}/revoke"
    )


def consume_url(machine_id, grant_id):
    return (
        f"/machines/{machine_id}/authorization-grants/{grant_id}/consume"
    )


def integrity_url(machine_id):
    return (
        f"/machines/{machine_id}"
        "/authorization-grant-lifecycle-events/integrity"
    )


def batch_revoke(client, machine_id, grant_ids):
    return client.post(
        batch_revoke_url(machine_id), json={"grant_ids": grant_ids}
    )


def set_machine_status(client, machine_id, status):
    response = client.post(
        f"/machines/{machine_id}/status", json={"status": status}
    )
    assert response.status_code == 200
    return response


def _parse_z(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


@pytest.fixture
def granted_machine(client):
    """A machine with three active grants on three allowed events."""
    machine_id = create_machine(client)
    declare(client, machine_id)
    create_rule(client)
    grants = []
    for resource in ("res/1", "res/2", "res/3"):
        event = record_event(client, machine_id, resource=resource).json()
        assert event["allowed"] is True
        grants.append(issue(client, machine_id, event["id"]))
    return machine_id, grants


def _grant_row(client, grant_id):
    with client.app.state.engine.connect() as conn:
        return conn.execute(
            text(
                "SELECT status, consumed_at, revoked_at FROM "
                "authorization_grants WHERE id = :id"
            ).bindparams(id=grant_id)
        ).one()


def _use_rows(client, grant_id):
    with client.app.state.engine.connect() as conn:
        return conn.execute(
            text(
                "SELECT id FROM authorization_grant_uses WHERE grant_id = :id"
            ).bindparams(id=grant_id)
        ).all()


def _lifecycle_events(client, grant_id):
    with client.app.state.engine.connect() as conn:
