# Concurrency
# --------------------------------------------------------------------------- #


def test_concurrent_revoke_batches_have_exactly_one_winner(
    granted_machine, client
):
    machine_id, grants = granted_machine
    grant_ids = [g["id"] for g in grants]
    gate = threading.Event()

    def hit():
        gate.wait()
        return batch_revoke(client, machine_id, grant_ids)

    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = [pool.submit(hit) for _ in range(10)]
        gate.set()
        responses = [f.result() for f in futures]

    statuses = sorted(r.status_code for r in responses)
    assert statuses.count(200) == 1
    assert statuses.count(409) == 9
    for response in responses:
        if response.status_code == 409:
            assert response.json() == {"error": {"code": "grant_revoked"}}

    for grant_id in grant_ids:
        row = _grant_row(client, grant_id)
        assert row.status == "revoked"
        # Exactly one revoked event per grant.
        assert _lifecycle_types(client, grant_id) == ["issued", "revoked"]


def test_concurrent_batch_and_single_revoke_have_one_winner(
    granted_machine, client
):
    machine_id, grants = granted_machine
    grant_ids = [g["id"] for g in grants]
    gate = threading.Event()

    def batch_hit():
        gate.wait()
        return batch_revoke(client, machine_id, grant_ids)

    def single_hit():
        gate.wait()
        return client.post(revoke_url(machine_id, grants[1]["id"]))

    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = [pool.submit(batch_hit) for _ in range(4)]
        futures += [pool.submit(single_hit) for _ in range(4)]
        gate.set()
        responses = [f.result() for f in futures]

    successes = [r for r in responses if r.status_code == 200]
    # Either exactly one batch succeeded, or exactly one single revoke
    # succeeded (and then every batch fails on the revoked grant).
    batch_wins = [r for r in successes if isinstance(r.json(), list)]
    single_wins = [r for r in successes if isinstance(r.json(), dict)]
    assert len(batch_wins) + len(single_wins) == 1

    for grant_id in grant_ids:
        row = _grant_row(client, grant_id)
        assert row.status == "revoked"
        assert _lifecycle_types(client, grant_id) == ["issued", "revoked"]
    if single_wins:
        for response in responses:
            if response.status_code == 409:
                assert response.json() == {
                    "error": {"code": "grant_revoked"}
                }


def test_concurrent_batch_revoke_and_single_consume_have_one_winner(
    granted_machine, client
):
    machine_id, grants = granted_machine
    grant_ids = [g["id"] for g in grants]
    gate = threading.Event()

    def batch_hit():
        gate.wait()
        return batch_revoke(client, machine_id, grant_ids)

    def single_consume_hit():
        gate.wait()
        return client.post(consume_url(machine_id, grants[1]["id"]))

    with ThreadPoolExecutor(max_workers=8) as pool:
        revoke_futures = [pool.submit(batch_hit) for _ in range(4)]
        consume_futures = [pool.submit(single_consume_hit) for _ in range(4)]
        gate.set()
        revoke_responses = [f.result() for f in revoke_futures]
        consume_responses = [f.result() for f in consume_futures]

    successful_revokes = [
        r for r in revoke_responses if r.status_code == 200
    ]
    successful_consumes = [
        r for r in consume_responses if r.status_code == 200
    ]
    # Exactly one terminal winner across the revocation and consumption.
    assert len(successful_revokes) + len(successful_consumes) == 1

    target = grants[1]["id"]
    if successful_consumes:
        # Consumption committed first: every batch observes consumed and
        # rolls back, leaving the other grants active.
        assert _grant_row(client, target).status == "consumed"
        assert _grant_row(client, grants[0]["id"]).status == "active"
        assert _grant_row(client, grants[2]["id"]).status == "active"
        for response in revoke_responses:
            assert response.status_code == 409
            assert response.json() == {
                "error": {"code": "grant_consumed"}
            }
        assert len(_use_rows(client, target)) == 1
    else:
        # A batch revocation committed first: every consumption observes
        # the revoked grant and every other batch sees it revoked too.
        assert _grant_row(client, target).status == "revoked"
        assert len(_use_rows(client, target)) == 0
        for response in consume_responses:
            assert response.status_code == 409
            assert response.json() == {
                "error": {"code": "grant_revoked"}
            }


def test_concurrent_batch_revoke_and_batch_consume_have_one_winner(
    granted_machine, client
):
    machine_id, grants = granted_machine
    grant_ids = [g["id"] for g in grants]
    gate = threading.Event()

    def revoke_hit():
        gate.wait()
        return batch_revoke(client, machine_id, grant_ids)

    def consume_hit():
        gate.wait()
        return client.post(
            batch_consume_url(machine_id), json={"grant_ids": grant_ids}
        )

    with ThreadPoolExecutor(max_workers=8) as pool:
        revoke_futures = [pool.submit(revoke_hit) for _ in range(4)]
        consume_futures = [pool.submit(consume_hit) for _ in range(4)]
        gate.set()
        revoke_responses = [f.result() for f in revoke_futures]
        consume_responses = [f.result() for f in consume_futures]

    successful_revokes = [
        r for r in revoke_responses if r.status_code == 200
    ]
    successful_consumes = [
        r for r in consume_responses if r.status_code == 200
    ]
    # Exactly one terminal winner between the two batch kinds.
    assert len(successful_revokes) + len(successful_consumes) == 1

    if successful_consumes:
        for grant_id in grant_ids:
            assert _grant_row(client, grant_id).status == "consumed"
            assert len(_use_rows(client, grant_id)) == 1
        for response in revoke_responses:
            assert response.json() == {
                "error": {"code": "grant_consumed"}
            }
    else:
        for grant_id in grant_ids:
            assert _grant_row(client, grant_id).status == "revoked"
            assert _use_rows(client, grant_id) == []
        for response in consume_responses:
            assert response.json() == {
                "error": {"code": "grant_revoked"}
            }


# --------------------------------------------------------------------------- #
# Non-interference with the single-revoke entry
# --------------------------------------------------------------------------- #


def test_single_revoke_still_works_after_batch(granted_machine, client):
    machine_id, grants = granted_machine
    assert batch_revoke(
        client, machine_id, [grants[0]["id"]]
    ).status_code == 200
    # A grant the batch left alone still revokes through the single entry.
    response = client.post(revoke_url(machine_id, grants[1]["id"]))
    assert response.status_code == 200
    assert list(response.json().keys()) == [
        "grant_id",
        "revoked_at",
        "status",
    ]
    # And the batch-revoked grant reports revoked through the single entry.
    repeat = client.post(revoke_url(machine_id, grants[0]["id"]))
    assert repeat.status_code == 409
    assert repeat.json() == {"error": {"code": "grant_revoked"}}


def test_repeated_batch_after_success_is_grant_revoked(
    granted_machine, client
):
    machine_id, grants = granted_machine
    grant_ids = [g["id"] for g in grants]
    assert batch_revoke(client, machine_id, grant_ids).status_code == 200
    repeat = batch_revoke(client, machine_id, grant_ids)
    assert repeat.status_code == 409
    assert repeat.json() == {"error": {"code": "grant_revoked"}}
    # Still exactly one revoked event per grant.
    for grant in grants:
        assert _lifecycle_types(client, grant["id"]) == [
            "issued",
            "revoked",
        ]


def test_batch_revoked_grant_is_rejected_by_consume(granted_machine, client):
    machine_id, grants = granted_machine
    assert batch_revoke(
        client, machine_id, [grants[0]["id"]]
    ).status_code == 200
    # The committed batch revocation wins the terminal-state race against
    # both consume entries.
    single = client.post(consume_url(machine_id, grants[0]["id"]))
    assert single.status_code == 409
    assert single.json() == {"error": {"code": "grant_revoked"}}
    batch = client.post(
        batch_consume_url(machine_id),
        json={"grant_ids": [grants[0]["id"]]},
    )
    assert batch.status_code == 409
    assert batch.json() == {"error": {"code": "grant_revoked"}}
